INSERT INTO `command` (`name`, `security`, `help`) VALUES
('ip power', 0, 'Syntax: .ip power [$damage [$healing] | reset]\nInside a dungeon or raid: shows, sets or resets the damage and healing factors used in this instance in place of the Power and Healing adjustments from the config. A factor is used as typed at every level (0.5 = half, 1 = full strength, the most it can be), for the characters those adjustments apply to. Leave $healing out to keep it as it is. Lasts until .ip power reset, an instance reset or a server restart. IndividualProgression.InstancePower.GMOnly limits changes to game masters.');
